<?php $formType=field('type',$formType); if(!in_array($formType,['personal','company'],true)) $formType='personal'; $sameType=$verification && $verification['type']===$formType; ?>
<?php if($error): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif ?>
<section class="panel verification-summary"><div><h2>认证进度</h2><span class="verification-tag <?= e($verification['status']??'unverified') ?>"><?= e(verificationStatus($verification)) ?></span></div><?php if($verification): ?><p><?= verificationType($verification['type']) ?> · <?= e($verification['subject_name']) ?></p><p class="muted">提交时间：<?= e($verification['submitted_at']) ?><?php if($verification['reviewed_at']): ?>　审核时间：<?= e($verification['reviewed_at']) ?><?php endif ?></p><?php if($verification['status']==='rejected'): ?><p class="rejection">驳回原因：<?= e($verification['rejection_reason']) ?></p><?php elseif($verification['status']==='pending'): ?><p class="muted">材料已提交，等待管理员审核。更新并提交后，将以最新材料重新审核。</p><?php else: ?><p class="muted">身份认证已通过。变更姓名、企业名称或证件材料后，需要重新审核。</p><?php endif ?><?php else: ?><p class="muted">请选择个人或企业认证，提交对应的证件材料。</p><?php endif ?></section>
<nav class="topic-nav" aria-label="认证类型"><?php foreach(['personal'=>'个人认证','company'=>'企业认证'] as $type=>$label): ?><a href="<?= e(memberUrl('verification',['type'=>$type])) ?>#verification-form" class="<?= $formType===$type?'active':'' ?>" <?= $formType===$type?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach ?></nav>
<section class="panel admin-form member-verification-form" id="verification-form"><h2><?= verificationType($formType) ?>材料</h2><form method="post" enctype="multipart/form-data" class="stack-form"><?= csrfField() ?><input type="hidden" name="type" value="<?= e($formType) ?>"><label><?= $formType==='personal'?'真实姓名':'企业名称' ?><input name="subject_name" value="<?= e(field('subject_name',$sameType?$verification['subject_name']:'')) ?>" minlength="2" maxlength="120" autocomplete="<?= $formType==='personal'?'name':'organization' ?>" required></label><div class="verification-upload-grid">
<?php foreach(verificationRoles($formType) as $role=>$label): $file=$sameType?($documents[$role]??null):null; ?>
<div class="verification-upload"><h3><?= e($label) ?></h3><?php if($file): ?><a class="verification-document" href="/yong-hu-zhong-xin/zheng-jian/<?= $file['id'] ?>/" target="_blank" rel="noopener"><img src="/yong-hu-zhong-xin/zheng-jian/<?= $file['id'] ?>/" alt="已上传的<?= e($label) ?>"><span>查看已上传材料</span></a><?php else: ?><div class="verification-upload-placeholder" aria-hidden="true"><span>＋</span><?= e($label) ?></div><?php endif ?><label>上传<?= e($label) ?><input type="file" name="<?= $role ?>[]" accept="image/jpeg,image/png,image/webp" data-image-limit="1" <?= $file?'':'required' ?>><small class="field-help"><?= $file?'不选择新图片则保留现有材料。':'请上传清晰、完整的证件图片。' ?></small></label></div>
<?php endforeach ?></div><div class="verification-privacy"><strong>材料仅用于平台身份认证审核</strong><p>仅本人和平台管理员可以查看，证件图片不在公开信息页面展示。每张最大 5MB，支持 JPEG、PNG、WebP；提交后由管理员人工审核。</p></div><div class="form-actions"><button class="button"><?= $verification?'更新材料并重新提交':'提交认证' ?></button><a class="text-link" href="<?= e(memberUrl()) ?>">返回管理首页</a></div></form></section>
